data.document:
query MexFetchNewsletterJobQuery($fetch_creation_time, $fetch_full_image, $fetch_pinned_messages, $fetch_status_metadata, $fetch_viewer_metadata, $fetch_wamo_sub, $input) {
  id
  type
  text
  update_time
  direct_path
  value
  xwa2_newsletter {
    state {
      thread_metadata {
        creation_time
        name {
          picture {
            picture {
              description {
                invite
                handle
                subscribers_count
                verification
                settings {
                  reaction_codes {
                    wamo_sub {
                      plan_id
                      pinned_messages {
                        message_id
                        expiry_ts
                        viewer_metadata {
                          settings {
                            role
                            wamo_sub_status
                            status_metadata {
                              last_status_server_id
                              last_status_sent_time
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
